def insertion_sort_movements(arr):
        movimientos = 0
        n = len(arr)
        for i in range(1, n):
                key = arr[i]
                j = i - 1
                while j >= 0 and arr[j] > key:
                        arr[j + 1] = arr[j]
                        j -= 1
                        movimientos += 1
                arr[j + 1] = key
        return movimientos
while True:
        try:
                arr = list(map(int,input().split()))
                print(insertion_sort_movements(arr))
        except EOFError:
