   c = 0
   if len(set(lis)) == 1:
      return c
   for i in range(1, len(lis)):
      k = lis[i]
      j = i - 1
      while j >= 0 and k < lis[j]:
         lis[j + 1] = lis[j]
         j -= 1
         c += 1
      lis[j + 1] = k
   return c

