import sys

def procesar_texto(texto):
  resultado = []
  buffer = []
  insertar_al_principio = False

  for char in texto:
    if char == '[':
      if insertar_al_principio:
        resultado = buffer + resultado
      else:
        resultado.extend(buffer)
      buffer = []
      insertar_al_principio = True
    elif char == ']':
      if insertar_al_principio:
        resultado = buffer + resultado
      else:
        resultado.extend(buffer)
      buffer = []
      insertar_al_principio = False
    else:
      if insertar_al_principio:
        buffer.append(char)
      else:
        resultado.append(char)

  if insertar_al_principio:
    resultado = buffer + resultado
  else:
    resultado.extend(buffer)

  return ''.join(resultado)

def main():
  input = sys.stdin.read()
  lineas = input.splitlines()

  for linea in lineas:
    print(procesar_texto(linea))

if __name__ == "__main__":
  main()

