def procesar_texto_beiju(linea):
   resultado_inicio = []
   resultado_final = []
   insertar_inicio = False
   for char in linea:
      if char == '[':
         insertar_inicio = True
         resultado_inicio.append("")
      elif char == ']':
         insertar_inicio = False
      else:
         if insertar_inicio:
            resultado_inicio[-1] += char
         else:
            resultado_final.append(char)
   return "".join(resultado_inicio[::-1]) + "".join(resultado_final)
