        input = sys.stdin.read
        data = input().strip().split()
        i = 0

        while i < len(data):
                n = int(data[i])
                i += 1
                commands = []
                for _ in range(n):
                        op = int(data[i])
                        x = int(data[i+1])
                        commands.append((op, x))
                        i += 2
                print(determine_structure(commands))

if __name__ == "__main__":
        main()

