def simulate_ball_drop(depth, ball_number):
  tree_size = 2**depth - 1
  flags = [False] * (tree_size + 1)  

  current_position = 1
  for _ in range(ball_number):
    current_position = 1  
    while current_position <= tree_size // 2:  
      if not flags[current_position]:
        flags[current_position] = True
        current_position = current_position * 2  
      else:
        flags[current_position] = False
        current_position = current_position * 2 + 1  

  return current_position

