def is_prime(num):
  if num < 2:
    return False
  for i in range(2, int(num ** 0.5) + 1):
    if num % i == 0:
      return False
  return True

def generate_primes():
  primes = []
  for num in range(1000, 10000):
    if is_prime(num):
      primes.append(num)
  return primes

def generate_neighbors(prime, primes_set):
  neighbors = []
  str_prime = str(prime)
  for i in range(4):
    for digit in '0123456789':
      if digit != str_prime[i]:
        new_prime = str_prime[:i] + digit + str_prime[i+1:]
        new_prime_num = int(new_prime)
        if new_prime_num in primes_set and new_prime_num != prime:
          neighbors.append(new_prime_num)
  return neighbors

def bfs(start, end, primes_set):
  queue = deque([(start, 0)])
  visited = set([start])

  while queue:
    current, cost = queue.popleft()

    if current == end:
      return cost

    for neighbor in generate_neighbors(current, primes_set):
      if neighbor not in visited:
        visited.add(neighbor)
        queue.append((neighbor, cost + 1))

  return -1

