def camino_corto(ini, fin):
    def generar_primos():
        primos = set()
        es_primo = [True] * 10000

        for i in range(2, int(10000**0.5) + 1):
            if es_primo[i]:
                for j in range(i*i, 10000, i):
                    es_primo[j] = False

        for i in range(1000, 10000):
            if es_primo[i]:
                primos.add(i)

        return primos

    def obtener_vecinos(num, primos):
        vecinos = []
        digitos = list(str(num))

        for i in range(4):
            digito_original = digitos[i]
            for c in '0123456789':
                if c != digito_original:
                    digitos[i] = c
                    vecino = int(''.join(digitos))
                    if vecino in primos:
                        vecinos.append(vecino)
            digitos[i] = digito_original

        return vecinos

    primos = generar_primos()
    if ini not in primos or fin not in primos:
        return -1

    queue = deque()
    dist = {}
    queue.append(ini)
    dist[ini] = 0

    while queue:
        actual = queue.popleft()
        if actual == fin:
            return dist[actual]

        vecinos = obtener_vecinos(actual, primos)
        for vecino in vecinos:
            if vecino not in dist:
                queue.append(vecino)
                dist[vecino] = dist[actual] + 1

    return -1

