def dfs(graph, visited, start):
  stack = [start]
  while stack:
    node = stack.pop()
    if not visited[node]:
      visited[node] = True
      for i in range(len(graph)):
        if graph[node][i] == 1 and not visited[i]:
          stack.append(i)

def find_dominators(n, graph):
  reachable = [False] * n
  dfs(graph, reachable, 0)
  dominator_matrix = [['N' for _ in range(n)] for _ in range(n)]
  for i in range(n):
    if reachable[i]:
      dominator_matrix[i][i] = 'Y'
  for i in range(n):
    if not reachable[i]:
      continue
    visited = [False] * n
    visited[i] = True
    dfs(graph, visited, 0)
    for j in range(n):
      if reachable[j] and not visited[j]:
        dominator_matrix[i][j] = 'Y'
  return dominator_matrix

