def ordenar_panqueques(pila):
  n = len(pila)
  volteos = []

  for i in range(n, 1, -1):
    max_pos = encontrar_maximo(pila, i)
    if max_pos != i - 1:
      if max_pos != 0:
        volteos.append(n - max_pos)
        pila = voltear(pila, max_pos + 1)
      volteos.append(n - i + 1)
      pila = voltear(pila, i)

  return volteos

while True:
  try:
    pila = list(map(int, input().split()))
    pila_original = pila.copy()
    print(*pila_original)

    volteos = ordenar_panqueques(pila)
    if volteos:
      print(*volteos, 0)
    else:
      print(0)

  except EOFError:
    break

