import math

def encontrar_formas(c, r):
    if c == r:
        return []

    n = c - r
    res = set()
    for i in range(1, int(math.sqrt(n)) + 1):
        if n % i == 0:
            if i > r:
                res.add(i)
            if (n // i) > r:
                res.add(n // i)
    return sorted(res)


