  def merge_and_count(arr, temp_arr, left, mid, right):
    i = left    
    j = mid + 1 
    k = left    
    inversiones = 0

    while i <= mid and j <= right:
      if arr[i] <= arr[j]:
        temp_arr[k] = arr[i]
        i += 1
      else:


        temp_arr[k] = arr[j]
        inversiones += (mid - i + 1)
        j += 1
      k += 1


    while i <= mid:
      temp_arr[k] = arr[i]
      i += 1
      k += 1


    while j <= right:
      temp_arr[k] = arr[j]
      j += 1
      k += 1


    for i in range(left, right + 1):
      arr[i] = temp_arr[i]

    return inversiones

  def merge_sort_and_count(arr, temp_arr, left, right):
    inversiones = 0
    if left < right:
      mid = (left + right) // 2

      inversiones += merge_sort_and_count(arr, temp_arr, left, mid)
      inversiones += merge_sort_and_count(arr, temp_arr, mid + 1, right)
      inversiones += merge_and_count(arr, temp_arr, left, mid, right)

    return inversiones

  n = len(arr)
  temp_arr = [0] * n
  return merge_sort_and_count(arr, temp_arr, 0, n - 1)

