def contar_inv(a):
   def m(l, r):
      if r - l <= 1: return 0
      m_ = (l + r) // 2
      i, j, inv = l, m_, 0
      inv += m(l, m_) + m(m_, r)
      tmp = []
      while i < m_ and j < r:
         if a[i] <= a[j]: tmp.append(a[i]); i += 1
         else: tmp.append(a[j]); inv += m_ - i; j += 1
      a[l:r] = tmp + a[i:m_] + a[j:r]
      return inv
   return m(0, len(a))
