         matches = re.findall(r'[a-zA-Z]+(?:-[a-zA-Z]+)?', palabra_actual)
         for palabra in matches:
            palabras.add(palabra.lower())
         palabra_actual = ""  

   return palabras

def main():
   palabras = leer_archivo()
   palabras_ordenadas = sorted(palabras)
   for palabra in palabras_ordenadas:
      print(palabra)

