def parse_guess(guess):
    import re


    operators = [">=", "<=", ">", "<", "="]
    for operator in operators:
        if operator in guess:
            left, right = guess.split(operator)
            left = left.strip().split(" + ")
            return left, operator, right.strip()
    return [], "", 0


def compare(left, operator, right):
    if operator == ">":
        return left > right
    elif operator == "<":
        return left < right
    elif operator == ">=":
        return left >= right
    elif operator == "<=":
        return left <= right
    elif operator == "=":
        return abs(left - right) < 1e-6  
    return False


