def compare_float(a, b, op):
  epsilon = 1e-9
  if op == '>':
    return a > b + epsilon
  elif op == '<':
    return a < b - epsilon
  elif op == '>=':
    return a >= b - epsilon
  elif op == '<=':
    return a <= b + epsilon
  elif op == '=':
    return abs(a - b) <= epsilon

def solve_election_forecast():
  parties_count, forecasts_count = map(int, input().split())
  election_results = {}
  for _ in range(parties_count):
    party, percentage = input().split()
    election_results[party] = float(percentage)
  for forecast_num in range(1, forecasts_count + 1):
    forecast = input()
    parts = forecast.split()
    operator_index = -1
    for i, part in enumerate(parts):
      if part in ['>', '<', '>=', '<=', '=']:
        operator_index = i
        break
    left_parties = parts[:operator_index]
    comparison_operator = parts[operator_index]
    right_value = float(parts[operator_index + 1])
    total_percentage = sum(election_results[party] for party in left_parties if party != '+')
    is_correct = compare_float(total_percentage, right_value, comparison_operator)
    print(f"Guess #{forecast_num} was {'correct' if is_correct else 'incorrect'}.")

