import math

def calcular_margen(linea):
  articulos = linea.strip().split(',')
  total_venta = 0.0
  total_costo = 0.0

  for articulo in articulos:
    precio = float(articulo[:6])
    costo = float(articulo[7:])
    total_venta += precio
    total_costo += costo

  ganancia = total_venta - total_costo
  if total_venta == 0:
    return 0  # evitar división por cero

  margen = (ganancia / total_venta) * 100
  return math.floor(margen)

