                        d = int(x % 10)
                        x = int(x / 10)
                        val = val | (1 << d)
                while(y > 0):
                        d = int(y % 10)
                        y = int(y / 10)
                        val = val | (1 << d)
                if(val == comp):
                        flag = True
                        stdout.write(str(abcde)+" / "+str(fghij)+" "+str(n)+"\n")
        if(flag == False):
                stdout.write("No hay soluciones para"+" "+str(n)+"\n")

