def find_pairs(N):
  solutions = []
  for denominator in range(1234, 98766):
    numerator = N * denominator
    if numerator > 98765:
      break
    combined = f"{numerator:05d}{denominator:05d}"
    if len(set(combined)) == 10 and '0' in combined:
      solutions.append(f"{numerator} / {denominator} {N}")
  return solutions

