def format_polynomial(coefficients):
    terms = []
    for i, coeff in enumerate(coefficients):
        degree = len(coefficients) - 1 - i
        if coeff != 0:
            if degree == 0:
                terms.append(f"{coeff}")
            elif degree == 1:
                terms.append(f"{'' if coeff == 1 else '-' if coeff == -1 else coeff}x")
            else:
                terms.append(f"{'' if coeff == 1 else '-' if coeff == -1 else coeff}x^{degree}")

    if not terms:
        return "0"

    formatted_polynomial = terms[0]
    for term in terms[1:]:
        if term.startswith('-'):
            formatted_polynomial += f" {term}"
        else:
            formatted_polynomial += f" + {term}"

    return formatted_polynomial.replace(' -', ' - ')  

