def process_case(n, first_row, first_col):
        matrix = [[0] * n for _ in range(n)]
        for j in range(n):
                matrix[0][j] = first_row[j]
        for i in range(n):
                matrix[i][0] = first_col[i]
        for i in range(1, n):
                for j in range(1, n):
                        matrix[i][j] = matrix[i][j-1] + matrix[i-1][j] + matrix[i-1][j-1]
        return matrix[n-1][n-1]
