def process_text(text):
  from collections import defaultdict
  pair_count = defaultdict(int)
  words = text.split()

  for word in words:
    for i in range(len(word) - 1):
      pair = word[i:i+2]
      pair_count[pair] += 1
  filtered_pairs = {pair: count for pair, count in pair_count.items() if count > 3}
  sorted_pairs = sorted(filtered_pairs.items())

  return sorted_pairs

