import sys

# Mapea 'a'..'z' a 0..25; rompe palabra en cualquier otro char
def procesar_linea(linea: str) -> None:
  counts = [0] * (26 * 26)  # 26x26 pares
  prev = -1  # índice de la letra anterior dentro de la palabra actual

  for ch in linea:
    o = ord(ch)
    if 65 <= o <= 90:       # 'A'..'Z'
      idx = o + 32 - 97   # a..z
    elif 97 <= o <= 122:    # 'a'..'z'
      idx = o - 97
    else:
      prev = -1           # separador: fin de palabra
      continue

    if prev != -1:
      counts[prev * 26 + idx] += 1
    prev = idx

  # Salida en orden alfabético (primera letra, luego segunda)
  wrote_any = False
  out = []
  for i in range(26):
    c1 = chr(97 + i)
    base = i * 26
    for j in range(26):
      freq = counts[base + j]
      if freq > 3:
        out.append(f"{c1}{chr(97 + j)} {freq}")
        wrote_any = True

  if wrote_any:
    sys.stdout.write("\n".join(out) + "\n")
  sys.stdout.write("----------\n")


def main():
  for linea in sys.stdin:
    # El ejemplo del enunciado muestra una línea en blanco de formato;
    # la ignoramos para no producir un caso vacío extra.
    if linea.strip():
      procesar_linea(linea)

