def convertir_a_notacion_numerica(celda):
  if celda[0].isalpha():
    columna = ord(celda[0].lower()) - ord('a') + 1
    fila = int(celda[1:])
    return (fila - 1) * 8 + columna
  else:
    numero = int(celda)
    fila = (numero - 1) // 8 + 1
    columna = (numero - 1) % 8
    return chr(ord('a') + columna) + str(fila)

