def generate_chess_pattern(rows, cols):

    board = []
    for i in range(rows):
        row = []
        for j in range(cols):


            if (i + j) % 2 == 0:
                row.append('.')
            else:
                row.append('X')
        board.append(row)

    if board[rows-1][cols-1] == 'X':

        for i in range(rows):
            for j in range(cols):
                board[i][j] = '.' if board[i][j] == 'X' else 'X'

    return board

