def generar_criba(n):
  es_primo = [True] * (n + 1)
  es_primo[0] = es_primo[1] = False

  for i in range(2, int(n**0.5) + 1):
    if es_primo[i]:
      for j in range(i * i, n + 1, i):
        es_primo[j] = False

  return es_primo

def obtener_primos(n):
  criba = generar_criba(n)
  return [i for i in range(len(criba)) if criba[i]]

def factorizar(n, primos):
  factores = []
  original_n = n
  for primo in primos:
    if primo * primo > n:
      break

    while n % primo == 0:
      factores.append(primo)
      n //= primo
  if n > 1:
    ultimo_primo = primos[-1]
    i = ultimo_primo
    while i * i <= n and n > 1:
      while n % i == 0:
        factores.append(i)
        n //= i
      i += 2

    if n > 1:
      factores.append(n)
  producto = 1
  for f in factores:
    producto *= f
  assert producto == original_n, f"Error: {original_n} != {producto}"

  return factores

def main():
  LIMITE = 10**6  
  primos = obtener_primos(LIMITE)

  try:
    while True:
      n = int(input())
      factores = factorizar(n, primos)
      print(*factores)
  except EOFError:
    pass

if __name__ == "__main__":
  main()

