def fibonacci_mod_period(a):
  previous, current = 0, 1
  period_length = 0
  seen = {}
  for i in range(0, a * a): 
    remainder = previous % a
    if (previous, current) in seen:
      return period_length
    seen[(previous, current)] = period_length
    previous, current = current, (previous + current) % a
    period_length += 1
  return period_length
