        combinacion = []

    if objetivo == 0 and len(combinacion) >= 2:
        return combinacion

    if indice >= len(lista) or objetivo < 0:
        return None

    combinacion.append(lista[indice])
    resultado = combinaciones(lista, objetivo - lista[indice], indice + 2, combinacion)
    if resultado:
        return resultado

    combinacion.pop()
    return combinaciones(lista, objetivo, indice + 1, combinacion)

