# Fibonacci con límite
def fibonacci(limite):
  fib_sec = [0, 1]
  while True:
    next_fib = fib_sec[-1] + fib_sec[-2]
    if next_fib >= limite:
      break
    fib_sec.append(next_fib)
  return fib_sec

