from collections import deque

def time_to_print(priorities, position):
  queue = deque([(priority, idx) for idx, priority in enumerate(priorities)])
  count = 0

  while queue:
    current = queue.popleft()

    if any(current[0] < job[0] for job in queue):
      queue.append(current)
    else:
      count += 1
      if current[1] == position:
        return count

