def calcular_tiempo_espera(n, m, cola):

    cola = deque(cola)


    tiempo = 0

    while True:

        max_prioridad = max(cola)  


        trabajo = cola.popleft()  
        m = m - 1  

        if trabajo == max_prioridad:

            tiempo += 1
            if m == -1:

                break
        else:

            cola.append(trabajo)
            if m == -1:
                m = len(cola) - 1

    return tiempo

