    self.heap = []

  def push(self, x):
    heapq.heappush(self.heap, -x)

  def pop(self):
    if self.heap:
      return -heapq.heappop(self.heap)
    else:
      return "Error"

  def top(self):
    if self.heap:
      return -self.heap[0]
    else:
      return "Error"

  def increment(self, x):
    if self.heap:
      max_elem = -heapq.heappop(self.heap)
      max_elem += x
      heapq.heappush(self.heap, -max_elem)
    else:
      return "Error"

  def decrement(self, x):
    if self.heap:
      max_elem = -heapq.heappop(self.heap)
      max_elem -= x
      heapq.heappush(self.heap, -max_elem)
    else:
      return "Error"

