    elif operacion == "R":
      if max_heap:
        heapq.heappop(max_heap)
      else:
        resultados.append("Error")
    elif operacion.startswith("I "):
      if max_heap:
        partes = operacion.split(" ")
        x = int(partes[1])
        max_val = -heapq.heappop(max_heap)
        heapq.heappush(max_heap, -(max_val + x))
      else:
        resultados.append("Error")
