import heapq
from collections import Counter

class NumberCollection:
  def __init__(self):
    self.heap = []  
    self.counter = Counter()  

  def store(self, x):

    heapq.heappush(self.heap, -x)
    self.counter[x] += 1

  def print_max(self):
    if not self.heap:
      print("Error")
      return

    print(-self.heap[0])

  def remove_max(self):
    if not self.heap:
      print("Error")
      return

    max_num = -heapq.heappop(self.heap)
    self.counter[max_num] -= 1
    if self.counter[max_num] == 0:
      del self.counter[max_num]

  def increment(self, x):
    if not self.heap:
      print("Error")
      return


    old_max = -heapq.heappop(self.heap)
    self.counter[old_max] -= 1
    if self.counter[old_max] == 0:
      del self.counter[old_max]


    new_max = old_max + x
    heapq.heappush(self.heap, -new_max)
    self.counter[new_max] += 1

  def decrement(self, x):
    if not self.heap:
      print("Error")
      return


    old_max = -heapq.heappop(self.heap)
    self.counter[old_max] -= 1
    if self.counter[old_max] == 0:
      del self.counter[old_max]


    new_max = old_max - x
    heapq.heappush(self.heap, -new_max)
    self.counter[new_max] += 1

def main():
  collection = NumberCollection()

  while True:
    try:
      command = input().strip()
      if command == 'T':
