      parts = command.split()
      operation = parts[0]

      if operation == 'S':
        collection.store(int(parts[1]))
      elif operation == 'A':
        collection.print_max()
      elif operation == 'R':
        collection.remove_max()
      elif operation == 'I':
        collection.increment(int(parts[1]))
      elif operation == 'D':
        collection.decrement(int(parts[1]))

    except EOFError:
      break

