   def __init__(self):
      self.stack = []

   def S(self, x):

      self.stack.append(x)

   def A(self):

      if self.stack:
         print(max(self.stack))
      else:
         print("Error")

   def R(self):

      if self.stack:
         max_num = max(self.stack)
         self.stack.remove(max_num)
      else:
         print("Error")

   def I(self, x):

      if self.stack:
         max_num = max(self.stack)
         index = self.stack.index(max_num)
         self.stack[index] += x
      else:
         print("Error")

   def D(self, x):

      if self.stack:
         max_num = max(self.stack)
         index = self.stack.index(max_num)
         self.stack[index] -= x
      else:
         print("Error")

