            if numeros:
                resultados.append(str(numeros[-1]))  
            else:
                resultados.append("Error")

        elif instruccion == 'R':

            if numeros:
                numeros.pop(-1)  
            else:
                resultados.append("Error")

        elif instruccion == 'I':

            if numeros:
