   c=0
   for k in range(len(s)):
      if s[k] == "A" and k % 4 == 1:
         c += 1
      elif s[k] == "B" and (k%4==0 or k%4==2):
         c += 1
      elif s[k] == "C" and k % 4 == 3:
         c += 1
   return c

def gab(s):
