   for k in range(len(s)):
      if s[k] == "A" and (k%6==2 or k%6==3):
         c += 1
      elif s[k] == "B" and (k%6==4 or k%6==5):
         c += 1
      elif s[k] == "C" and (k % 6 == 0 or k % 6 == 1):
         c += 1
   return c

