# Definir las secuencias de los tres estudiantes
def secuencia_alvaro(n):
  return ['A', 'B', 'C'] * (n // 3 + 1)

def secuencia_edwin(n):
  return ['B', 'A', 'B', 'C'] * (n // 4 + 1)

def secuencia_gabriel(n):
  return ['C', 'C', 'A', 'A', 'B', 'B'] * (n // 6 + 1)

# Función principal
def resolver_examen(n, respuestas):
  # Obtener las secuencias de los estudiantes
  alvaro_seq = secuencia_alvaro(n)[:n]
  edwin_seq = secuencia_edwin(n)[:n]
  gabriel_seq = secuencia_gabriel(n)[:n]

  # Contar las respuestas correctas para cada uno
  alvaro_correctas = sum(1 for i in range(n) if respuestas[i] == alvaro_seq[i])
  edwin_correctas = sum(1 for i in range(n) if respuestas[i] == edwin_seq[i])
  gabriel_correctas = sum(1 for i in range(n) if respuestas[i] == gabriel_seq[i])

  # Encontrar el máximo de respuestas correctas
  max_correctas = max(alvaro_correctas, edwin_correctas, gabriel_correctas)

  # Imprimir el número máximo de respuestas correctas
  print(max_correctas)

  # Determinar quiénes obtuvieron el máximo de respuestas correctas
  if alvaro_correctas == max_correctas:
    print("Alvaro")
  if edwin_correctas == max_correctas:
    print("Edwin")
  if gabriel_correctas == max_correctas:
    print("Gabriel")

