def rotarMatriz(matriz, grados):
  n = len(matriz[0])
  matrizRotada = [[0]*n for x in range(n)]
  if grados == 90:
    for i in range(n):
      for j in range(n):
        matrizRotada[j][n-i-1] = matriz[i][j]
  elif grados == 180:
    for i in range(n):
      for j in range(n):
        matrizRotada[n-i-1][n-j-1] = matriz[i][j]
  else:
    for i in range(n):
      for j in range(n):
        matrizRotada[n-j-1][i] = matriz[i][j]
  return matrizRotada

