def sieve_of_eratosthenes(n):
        is_prime = [True] * (n + 1)
        p = 2
        while (p * p <= n):
                if (is_prime[p]):
                        for i in range(p * p, n + 1, p):
                                is_prime[i] = False
                p += 1
        primes = [p for p in range(2, n + 1) if is_prime[p]]
        return primes

def count_unique_prime_factors(n, primes):
        count = 0
        for prime in primes:
                if prime * prime > n:
                        break
                if n % prime == 0:
                        count += 1
                        while n % prime == 0:
                                n //= prime
        if n > 1:  
                count += 1
        return count

def precompute_unique_prime_factors(limit):
        primes = sieve_of_eratosthenes(limit)
        unique_factors_count = [0] * (limit + 1)
        for i in range(2, limit + 1):
                unique_factors_count[i] = count_unique_prime_factors(i, primes)
        return unique_factors_count

