   import sys

   class UnionFind:
      def __init__(self, n):
         self.parent = list(range(n))
         self.rank = [0] * n
         self.size = [1] * n

      def find(self, x):
         # Compresión de caminos
         if self.parent[x] != x:
            self.parent[x] = self.find(self.parent[x])
         return self.parent[x]

      def union(self, x, y):
         root_x = self.find(x)
         root_y = self.find(y)

         if root_x == root_y:
            return

         # Unión por rango
         if self.rank[root_x] < self.rank[root_y]:
            self.parent[root_x] = root_y
            self.size[root_y] += self.size[root_x]
         elif self.rank[root_x] > self.rank[root_y]:
            self.parent[root_y] = root_x
            self.size[root_x] += self.size[root_y]
         else:
            self.parent[root_y] = root_x
            self.size[root_x] += self.size[root_y]
            self.rank[root_x] += 1

      def get_num_components(self):
         # Contar cuántos nodos son su propio padre
         return sum(1 for i in range(len(self.parent)) if self.find(i) == i)

      def get_max_component_size(self):
         # Encontrar el tamaño máximo entre todos los componentes
         roots = {}
         for i in range(len(self.parent)):
            root = self.find(i)
            if root not in roots:
               roots[root] = self.size[root]
         return max(roots.values()) if roots else 0

