def sieve_of_eratosthenes(max_num):
   is_prime = [True] * (max_num + 1)
   p = 2
   while (p * p <= max_num):
      if (is_prime[p]):
         for i in range(p * p, max_num + 1, p):
            is_prime[i] = False
      p += 1
   return [p for p in range(2, max_num + 1) if is_prime[p]]

def count_consecutive_prime_sums(max_num):
   primes = sieve_of_eratosthenes(max_num)
   prime_count = len(primes)
   representation_count = [0] * (max_num + 1)

   for start in range(prime_count):
      sum_primes = 0
      for end in range(start, prime_count):
         sum_primes += primes[end]
         if sum_primes > max_num:
            break
         representation_count[sum_primes] += 1

   return representation_count

