def get_primes(n: int) -> list:
  primes = [1] * (n + 1)
  primes[0] = primes[1] = 0
  for i in range(n+1):
    if primes[i] == 1:
      primes[i] = i
      for j in range(i+i, n+1, i):
        primes[j] = i
  return primes

def get_sum_factors(n: int, primes: list) -> str:
  factors = []
  while n > 1:
    factor = primes[n]
    factors.append(factor)
    n = n//factor
  return sum(set(factors))

