def find_ruth_aaron_pairs(a, b, prime_factors, prime_sums):
        """Encuentra y devuelve los pares de Ruth-Aaron en el rango [a, b]."""
        pairs = []
        for n in range(max(2, a), b):
                if prime_sums[n] == prime_sums[n + 1]:
                        pairs.append((n, n + 1))
        return pairs

