def contar_subconjuntos(i, suma_actual, elementos, suma_deseada):

    if i == len(elementos):

        return 1 if suma_actual == suma_deseada else 0


    incluir = contar_subconjuntos(i + 1, suma_actual + elementos[i], elementos, suma_deseada)


