def procesar_transacciones(t):
  s = {}
  for tr in t:
    p = tr.split()
    tipo = p[0]

    if tipo == "R":
      nombre = p[1]
      monto = int(p[2])
      if nombre in s:
        s[nombre] += monto
      else:
        s[nombre] = monto

    elif tipo == "G":
      nombre = p[1]
      monto = int(p[2])
      if nombre in s:
        s[nombre] -= monto
      else:
        s[nombre] = -monto

    elif tipo == "P":
      nombre_origen = p[1]
      monto = int(p[2])
      nombre_destino = p[3]
      if nombre_origen in s:
        s[nombre_origen] -= monto
      else:
        s[nombre_origen] = -monto
      if nombre_destino in s:
        s[nombre_destino] += monto
      else:
        s[nombre_destino] = monto

  return s

