import heapq
def calculate_statistics(nums):
   if not nums:
      return "sin elementos"
   minimum = min(nums)
   maximum = max(nums)
   average = sum(nums) / len(nums)
   return f"minimo: {minimum} maximo: {maximum} promedio {average:.4f}"
def main():
   nums = []
   min_heap = []  
   while True:
      try:
         line = input().strip()
         if line == "":
            continue
         if line.startswith("numero"):
            _, value = line.split()
            value = int(value)
            nums.append(value)
            heapq.heappush(min_heap, value)
         elif line == "borrar":
            if nums:
               min_value = heapq.heappop(min_heap)
               nums.remove(min_value)
               while min_heap and min_heap[0] not in nums:
                  heapq.heappop(min_heap)
         print(calculate_statistics(nums))
      except EOFError:
         break
if __name__ == "__main__":
   main()

