def calcular_clave(cadena):
  # Contar las frecuencias de cada letra en la cadena
  frecuencias = {}
  for letra in cadena:
    if letra in frecuencias:
      frecuencias[letra] += 1
    else:
      frecuencias[letra] = 1
  # Encontrar la letra con la frecuencia máxima
  max_frecuencia = max(frecuencias.values())
  return max_frecuencia

def obtener_valor_letra(letra):
  abecedario = 'ABCDEFGHIJKLMNÑOPQRSTUVWXYZ'
  return abecedario.index(letra) + 1

def obtener_letra_por_valor(valor):
  abecedario = 'ABCDEFGHIJKLMNÑOPQRSTUVWXYZ'
  if 1 <= valor <= 27:
    return abecedario[valor - 1]
  return ''

def desplazar_letra(letra, desplazamiento):
  valor_actual = obtener_valor_letra(letra)
  nueva_posicion = (valor_actual + desplazamiento - 1) % 27 + 1
  return obtener_letra_por_valor(nueva_posicion)

def cifrar_cadena(cadena):
  desplazamiento = calcular_clave(cadena)
  clave = obtener_letra_por_valor(desplazamiento)
  cadena_cifrada = clave
  for letra in cadena:
    cadena_cifrada += desplazar_letra(letra, desplazamiento)
  return cadena_cifrada

