import sys

# Construimos la lista del alfabeto español con Ñ
ALFABETO = [
    'A','B','C','D','E','F','G','H','I','J','K','L','M',
    'N','Ñ','O','P','Q','R','S','T','U','V','W','X','Y','Z'
]
# Mapa carácter → índice (1-based)
POS = {c: i+1 for i, c in enumerate(ALFABETO)}
M = len(ALFABETO)  # 27

def cifrar(palabra: str) -> str:
   # 1) calcular clave: máxima frecuencia de cualquier carácter
   from collections import Counter
   freqs = Counter(palabra)
   clave = max(freqs.values())
   # reducimos al rango 1–27 por si clave > 27
   clave = clave % M
   if clave == 0:
      clave = M

   # 2) prefijo: la letra correspondiente a 'clave'
   salida = [ALFABETO[clave-1]]

   # 3) procesar cada carácter
   for ch in palabra:
      if ch in POS:
         pos = POS[ch]
         np = pos + clave
         # wrap-around
         if np > M:
            np -= M
         salida.append(ALFABETO[np-1])
      else:
         # no es letra (número o símbolo): repetir tal cual
         salida.append(ch)
   return ''.join(salida)

def main():
   data = sys.stdin.read().strip().split()
   if not data:
      return
   it = iter(data)
   # puede haber varios casos hasta EOF
   while True:
      try:
         k = int(next(it))
      except StopIteration:
         break
      for _ in range(k):
         palabra = next(it)
         print(cifrar(palabra))

if __name__ == '__main__':
   main()

