from collections import Counter
def vamos_busca(ls, rs):
   LC = Counter(ls)
   RC = Counter(rs)
   T = 0
   AA = set(LC.keys()).union(set(RC.keys()))
   for lol in AA:
      lf = LC.get(lol, 0)
      rf = RC.get(lol, 0)
      T += abs(lf - rf)
   return T // 2
