  while lista[0]>0 or lista[1]>0 or lista[2]>0:
    contar_cuantos=0
    for j in range(len(lista)):
      if lista[j]>0:
        contar_cuantos+=1
        lista[j]-=1
    if contar_cuantos==3:
      final[0]+=1
    if contar_cuantos==2:
      final[1]+=1
    if contar_cuantos==1:
      final[2]+=1
  return final

