def calcular_hamburguesas(jamon, tocino, huevo):
  tres_ingredientes = 0
  dos_ingredientes = 0
  un_ingrediente = 0

  tres_ingredientes = min(jamon, tocino, huevo)

  jamon -= tres_ingredientes
  tocino -= tres_ingredientes
  huevo -= tres_ingredientes

  ingredientes = sorted([jamon, tocino, huevo], reverse=True)
  dos_ingredientes = min(ingredientes[0], ingredientes[1])

  if jamon >= tocino and jamon >= huevo:
    jamon -= dos_ingredientes
    if tocino >= huevo:
      tocino -= dos_ingredientes
    else:
      huevo -= dos_ingredientes
  elif tocino >= jamon and tocino >= huevo:
    tocino -= dos_ingredientes
    if jamon >= huevo:
      jamon -= dos_ingredientes
    else:
      huevo -= dos_ingredientes
  else:
    huevo -= dos_ingredientes
    if jamon >= tocino:
      jamon -= dos_ingredientes
    else:
      tocino -= dos_ingredientes

  un_ingrediente = max(jamon, tocino, huevo)

  return tres_ingredientes, dos_ingredientes, un_ingrediente

def main():
  n = int(input())

  for _ in range(n):
    jamon, tocino, huevo = map(int, input().split())
    tres, dos, uno = calcular_hamburguesas(jamon, tocino, huevo)
    print(f"{tres} {dos} {uno}")

if __name__ == "__main__":
  main()

def max_hamburgers(ingredients):
   three_ingredient_burgers = 0
   two_ingredient_burgers = 0
   one_ingredient_burgers = 0

   while ingredients[0] > 0 and ingredients[1] > 0 and ingredients[2] > 0:
      three_ingredient_burgers += 1
      ingredients = (ingredients[0] - 1, ingredients[1] - 1, ingredients[2] - 1)

   while (ingredients[0] > 0 and ingredients[1] > 0) or (ingredients[0] > 0 and ingredients[2] > 0) or (ingredients[1] > 0 and ingredients[2] > 0):
      if ingredients[0] > 0 and ingredients[1] > 0:
         two_ingredient_burgers += 1
         ingredients = (ingredients[0] - 1, ingredients[1] - 1, ingredients[2])
      elif ingredients[0] > 0 and ingredients[2] > 0:
         two_ingredient_burgers += 1
         ingredients = (ingredients[0] - 1, ingredients[1], ingredients[2] - 1)
      elif ingredients[1] > 0 and ingredients[2] > 0:
         two_ingredient_burgers += 1
         ingredients = (ingredients[0], ingredients[1] - 1, ingredients[2] - 1)

   one_ingredient_burgers = ingredients[0] + ingredients[1] + ingredients[2]

   return (three_ingredient_burgers, two_ingredient_burgers, one_ingredient_burgers)


