def count_ways(n):
  if n < 2:
    return 0 

  total_ways = n * n * (n * n - 1) // 2  
  attack_ways = 0

  for row in range(n):
    for col in range(n):

      attack_ways += (n - 1) + (n - 1)

      attack_ways += min(row, col) + min(n - 1 - row, n - 1 - col)

      attack_ways += min(row, n - 1 - col) + min(n - 1 - row, col)

  return total_ways - attack_ways // 2

