def process_match_results():
   from collections import defaultdict
   points = defaultdict(int) 
   while True:
      try:
         line = input().strip()
         if not line:
            break
         parts = line.split()
         action = parts[0]
         if action == 'E':
            team1, team2 = parts[1], parts[2]
            points[team1] += 1
            points[team2] += 1
         elif action == 'G':
            winner = parts[1]
            points[winner] += 2
      except EOFError:
         break
   sorted_teams = sorted(points.items(), key=lambda x: (-x[1], x[0]))
   for team, score in sorted_teams:
      print(f"{team} {score}")
if __name__ == "__main__":
   process_match_results()

