from math import gcd
def max_points_on_line_from_origin(points):
  slope_count = {}    
  for x, y in points:
    g = gcd(x, y)
    normalized_slope = (y // g, x // g)
    if normalized_slope in slope_count:
      slope_count[normalized_slope] += 1
    else:
      slope_count[normalized_slope] = 1
  return max(slope_count.values())
def main():
  n = int(input().strip())
  points = []
  for _ in range(n):
    x, y = map(int, input().strip().split())
    points.append((x, y))
  result = max_points_on_line_from_origin(points)
  print(result)

if __name__ == "__main__":
  main()

