def sum_digits_to_single_digit(number_str):
  while len(number_str) > 1:
    total_sum = sum(int(digit) for digit in number_str)
    number_str = str(total_sum)
  return number_str

def process_case(number_str, k):
  length = len(number_str)
  result = []


  for i in range(length - k + 1):

    group = number_str[i:i + k]

    single_digit_result = sum_digits_to_single_digit(group)

    result.append(single_digit_result)
  return ''.join(result)

def main():
  num_cases = int(input().strip())
  for _ in range(num_cases):
    number_str, k = input().strip().split()
    k = int(k)
    result = process_case(number_str, k)
    print(result)
