import sys

def has_cycle(graph):
  stack = []
  visited = set()
  on_stack = set()

  def dfs(node):
    if node in on_stack:
      return True
    if node in visited:
      return False

    visited.add(node)
    on_stack.add(node)
    stack.append(node)

    for neighbor in graph.get(node, []):
      if dfs(neighbor):
        return True

    on_stack.remove(node)
    stack.pop()
    return False

  for node in graph:
    if dfs(node):
      return True

  return False

