   # Escribir n-1 como d*2^r
   r = 0
   d = n - 1
   while d % 2 == 0:
      d //= 2
      r += 1

   # Aplicar k iteraciones del test de Miller-Rabin
   for _ in range(k):
      a = random.randint(2, n - 2)
      x = pow(a, d, n)
      if x == 1 or x == n - 1:
         continue
      for _ in range(r - 1):
         x = pow(x, 2, n)
         if x == n - 1:
