def flood_fill(grid, x, y):
  if x < 0 or x >= len(grid) or y < 0 or y >= len(grid[0]) or grid[x][y] == '#':
    return 0

  if grid[x][y] == '.' or grid[x][y] == '@':
    grid[x][y] = '#'  
    return 1 + flood_fill(grid, x+1, y) + flood_fill(grid, x-1, y) + \
               flood_fill(grid, x, y+1) + flood_fill(grid, x, y-1)

  return 0

