def sumnenk(n, k):
  ts = 0
  v = n
  m = {}
  secuencia = []

  for i in range(k + 1):
    if n % 2 == 0 and k % 2 == 0:
      v %= 9
    if n % 2 != 0 or k % 2 != 0:
      v %= 9
    if n % 2 != 0 and k % 2 != 0:
      v %= 9

    if v in m:
      ic = m[v]
      interc = i - ic
      csum = sum(secuencia[ic:])
      irr = k - i + 1
      ts += (irr // interc) * csum
      irr %= interc
      for j in range(irr):
        ts += secuencia[ic + j]
      return ts
    m[v] = i
    cuad = sumdigscuad(v)
    ts += cuad
    secuencia.append(cuad)
    v = cuad % 9
    if v == 0 and cuad != 0:
      v = 9

  return ts

