def generar_numeros_cuadrados(digitos):
  limite_inferior = 10**(digitos//2 - 1)
  limite_superior = 10**(digitos//2)
  resultados = []

  for i in range(limite_inferior, limite_superior):
    numero1 = i
    numero2 = i + 1
    numero_completo = int(f"{numero1}{numero2}")

    if es_cuadrado(numero_completo):
      resultados.append(numero_completo)

  return resultados

