def H(x, y, n, cad, v, lon):
  if y + n <= lon:
    for i in range(n):
      if v[x][y + i] != cad[i]:
        return False
    return True
  return False

def V(x, y, n, cad, v, cnt):
  if x + n <= cnt:
    for i in range(n):
      if v[x + i][y] != cad[i]:
        return False
    return True
  return False

def D(x, y, n, cad, v, cnt, lon):
  if x + n <= cnt and y + n <= lon:
    for i in range(n):
      if v[x + i][y + i] != cad[i]:
        return False
    return True
  return False

