  return int(s[1:] + s[0])

def rotate_right(number):
  s = str(number)
  return int(s[-1] + s[:-1])

def waliqui_rotation(N):
  binary = bin(N)[2:] 
  current_number = N
  for bit in binary:
    if bit == '1':
      current_number = rotate_left(current_number)
    else:
      current_number = rotate_right(current_number)
  return current_number

