  dp[n] = g(n - 1) + g(n - 2)
  return dp[n]
def multiplicar_matrix(A, B):
  global mod
  C = [[0, 0], [0, 0]]

  n = len(A)
  for i in range(n):
    for j in range(n):
      for k in range(n):
        C[i][j] += A[i][k] * B[k][j]
        C[i][j] %= mod
  return C


def fast_pow(A, n):
  ans = [[1, 0], [0, 1]]
  while n > 0:
    if n & 1:
      ans = multiplicar_matrix(ans, A)
    n >>= 1
    A = multiplicar_matrix(A, A)
  return ans
