    cd=int(math.log10(n))+1
    s=0
    while n!=0:
      d=n//10**(cd-1)
      n=n%10**(cd-1)
      cd=cd-1
      d2=n//10**(cd-1)
      if cd!=0:
        if d+d2>=10:
          s=s*10+((d+d2)%10)
        else:
          s=s*10+(d+d2)
    n=s
  return n

def encontrandoNum(cad):
  n=0
  for i in range(len(cad)):
    valor=sol(cad[i])
