def calcular_yuanfen(abreviatura: str) -> (int, str):

        letras = "A B C D E F G H I J K L M N Ñ O P Q R S T U V W X Y Z".split()
        mapa = {ch: i+1 for i, ch in enumerate(letras)}


        abre = abreviatura.strip().upper()
        digits_str = ""
        for ch in abre:
                if ch in mapa:
                        digits_str += str(mapa[ch])
                else:

                        continue


        digits = [int(c) for c in digits_str]

        while True:

                s = ''.join(str(d) for d in digits).lstrip('0')
                if s == "":
                        s = "0"


                if s == "100" or len(s) == 2:
                        resultado = int(s)
                        break


                next_digits = [ (digits[i] + digits[i+1]) % 10 for i in range(len(digits)-1) ]
                digits = next_digits

        estado = "PAREJA FELIZ" if resultado == 100 else "PAREJA INFELIZ"
        return resultado, estado

if __name__ == "__main__":
        s = input().strip()
        resultado, estado = calcular_yuanfen(s)
        print(f"{resultado} - {estado}")

