      return False
   for i in range(2, int(n ** 0.5) + 1):
      if n % i == 0:
         return False
   return True

def es_feliz(n):
   visitados = set()
   while n != 1 and n not in visitados:
      visitados.add(n)
      n = sum(int(digit) ** 2 for digit in str(n))
   return n == 1

