   for num in numeros:
      if suma % num == 0 and suma != num:
         divisores.append(num)
   return divisores

def procesar_lista(lista):
   suma_pares = [lista[i] + lista[j] for i in range(len(lista)) for j in range(i+1, len(lista))]
   divisores = [obtener_divisores(suma, lista) for suma in suma_pares]
   return suma_pares, divisores


