import math

def encontrar_potencia(a, b, c):
  producto = a * b * c
  max_potencia = int(math.log(producto, 2))  
  respuesta = (-1, -1)  
  for y in range(max_potencia, 1, -1):
    x = round(producto ** (1 / y))
    if x ** y == producto:
      respuesta = max(respuesta, (x, y))  
  return respuesta

