  while (i * i <= n):
    if p[i] == True:
      for j in range(i * i, n + 1, i):
        p[j] = False
    i += 1
  p[0], p[1] = False, False
  return [i for i in range(n + 1) if p[i]]

def contar(n, primos):
  f = set()
  for p in primos:
    if p * p > n:
      break
    if n % p == 0:
      f.add(p)
      while n % p == 0:
        n //= p
  if n > 1:
    f.add(n)
  return len(f)

